def links(ids,main=False):
 return ('links','Документы раздела',[(p['name'],('' if main else '../')+p['id']+'/index.html',p['about']) for p in PAGES if p['id'] in ids])
def tab(title,heads,rows,note=None):return ('table',title,heads,rows,note)
def p(t):return ('p',t)
def card(title,lines):return ('cards',[(title,None,lines)])

def supply_svg():
 # Функциональная схема: размеры шкафов и геометрия труб показаны отдельными таблицами.
 out=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1180 530" role="img" aria-label="Два независимых узла воды после счётчиков">',
 '<rect width="1180" height="530" fill="white"/>']
 def text(x,y,s,size=14):out.append(f'<text x="{x}" y="{y}" font-size="{size}" font-family="sans-serif" fill="#203040">{E(s)}</text>')
 for n,y,desc in [(1,55,'У1 · санузел у спален'),(2,310,'У2 · санузел у входа + кухня')]:
  text(20,y-20,desc,20)
  for kind,dy,col in [('ХВС',0,'#1971c2'),('ГВС',85,'#d9480f')]:
   yy=y+dy;text(20,yy+38,kind)
   out.append(f'<path d="M65 {yy+30} H1140" stroke="{col}" stroke-width="3"/>')
   boxes=[(75,100,'УК: учёт','кран/фильтр'),(200,110,'V'+str(n)+('C' if kind=='ХВС' else 'H'), 'автокран'),(335,110,'сервис /','промывной фильтр'),(475,110,'редуктор*','+ манометр'),(615,110,'обратный*','клапан'),(760,135,'К'+str(n)+'.'+('C' if kind=='ХВС' else 'H'),'коллектор')]
   for x,w,a,b in boxes:
    out.append(f'<rect x="{x}" y="{yy}" width="{w}" height="60" rx="5" fill="#fff" stroke="{col}"/>');text(x+7,yy+23,a);text(x+7,yy+44,b,12)
   work=3 if n==1 and kind=='ХВС' else 2 if n==1 else 5 if kind=='ХВС' else 3
   text(920,yy+24,f'{work} рабочих луча + 1 резерв');text(920,yy+45,'Каждый выход со своим краном',12)
 text(20,505,'* Наличие обратного клапана и необходимость редуктора — после осмотра узла застройщика и измерения давления.',14)
 out.append('</svg>');return ''.join(out)

def build(e):
 pipes=e['PIPES'];rooms={};rows=[];indices={};ports={}
 for kind,dest,r,pts,node in pipes:
  key=(node,kind);indices[key]=indices.get(key,0)+1
  mark=f'{node[-1]}.{"C" if kind=="c" else "H"}{indices[key]:02d}'
  length=e['pipe_len'](pts);ports[dest+kind]=mark
  rows.append([mark,node,e['RN'][r],dest,'ХВС' if kind=='c' else 'ГВС',f(length,2),'16×2,2; целый луч'])
 for r in e['ROOM_ORDER']:
  rr=e['water_rows'](r)
  rooms[r]=[tab('Точки подключения',['Прибор','Вода','Высота, см','Канализация / высота','Стояк'],rr,
    'Все высоты от будущего чистого пола. Горизонтальные выводы дополнительно привязать к осям мебели после выбора приборов.'),
    links(['razvodka','kanalizaciya','montazh'])] if rr else [p('В комнате нет приборов водоснабжения. Транзитные трассы не сверлить без исполнительного плана.'),links(['zadanie'])]
  if r in ('su-1','su-2'):
   rooms[r].append(('links','Конструкции этого санузла',[
    ('У05 · Мокрые стены и пол','../../remont/uzly/index.html#u05','Плитка, гидроизоляция, ленты и манжеты'),
    ('У06 · Дверь и порог','../../remont/uzly/index.html#u06','Граница деревянного и минерального пола'),
    ('У08 · Рама WC','../../remont/uzly/index.html#u08','Опирание, обшивка и доступ к обслуживанию'),
    ('У09 · Ванна' if r=='su-1' else 'У07 · Душевой лоток','../../remont/uzly/index.html#'+('u09' if r=='su-1' else 'u07'),'Примыкания и проверка до облицовки')]))
 sewer=[]
 for dest,dia,slope,pts in e['SEWER']:
  length=e['S'].path_len(pts)/100
  sewer.append([dest,str(dia),f(slope,0)+' %',f(length,2),f(length*slope,1)+' см',f'{pts[-1][0]}; {pts[-1][1]}'])
